<?php
declare(strict_types=1);
final class FileManager {
    public function __construct(private readonly array $config,private readonly WorkspaceService $ws){}
    public function act(string $action,string $path,string $dest=''):array{if($action==='mkdir')return $this->mkdir($path);$src=$this->ws->safe($path,true);return match($action){'rename'=>$this->rename($src,$dest),'move'=>$this->move($src,$dest),'trash'=>$this->trash($src,$path),'restore'=>$this->restore($path),default=>throw new InvalidArgumentException('Operação de arquivo inválida.')};}
    public function create(string $path,string $content,bool $confirmed=false):array{$f=$this->ws->safe($path,false);if(is_file($f)&&!$confirmed)return ['requer_confirmacao'=>true,'mensagem'=>'O arquivo já existe; confirme a substituição.'];$backup=$this->backup($f);if(!is_dir(dirname($f))&&!mkdir(dirname($f),0775,true))throw new RuntimeException('Não foi possível criar a pasta.');if(file_put_contents($f,$content,LOCK_EX)===false)throw new RuntimeException('Não foi possível criar o arquivo.');return ['ok'=>true,'path'=>$path,'backup'=>$backup];}
    public function copy(string $from,string $to,bool $confirmed=false):array{$src=$this->ws->safe($from,true);$dst=$this->ws->safe($to,false);if(!is_file($src))throw new RuntimeException('Origem não é arquivo.');if(is_file($dst)&&!$confirmed)return ['requer_confirmacao'=>true,'mensagem'=>'O destino já existe; confirme a substituição.'];$backup=$this->backup($dst);if(!is_dir(dirname($dst))&&!mkdir(dirname($dst),0775,true))throw new RuntimeException('Não foi possível criar a pasta.');if(!copy($src,$dst))throw new RuntimeException('Não foi possível copiar.');return ['ok'=>true,'origem'=>$from,'destino'=>$to,'backup'=>$backup];}
    public function delete(string $path,bool $confirmed=false):array{if(!$confirmed)return ['requer_confirmacao'=>true,'mensagem'=>'Confirme a exclusão.'];$f=$this->ws->safe($path,true);if(!is_file($f))throw new RuntimeException('Somente arquivos podem ser excluídos por esta operação.');$backup=$this->backup($f);if(!unlink($f))throw new RuntimeException('Não foi possível excluir o arquivo.');return ['ok'=>true,'path'=>$path,'backup'=>$backup];}
    private function backup(string $f):?string{if(!is_file($f))return null;$dir=$this->ws->root().DIRECTORY_SEPARATOR.'.backups';if(!is_dir($dir)&&!mkdir($dir,0700,true))return null;$name=date('Ymd_His').'__'.bin2hex(random_bytes(3)).'__'.basename($f);$target=$dir.DIRECTORY_SEPARATOR.$name;if(!copy($f,$target))return null;return '.backups/'.$name;}
    private function mkdir(string $path):array{$new=$this->ws->safe($path,false);if(file_exists($new))throw new RuntimeException('Pasta já existe.');if(!mkdir($new,0775,true))throw new RuntimeException('Não foi possível criar a pasta.');return ['path'=>$path];}
    private function rename(string $src,string $dest):array{$parent=dirname($src);$name=basename(trim($dest));if($name===''||preg_match('/[\\\/\0]/',$name))throw new InvalidArgumentException('Nome inválido.');$new=$parent.DIRECTORY_SEPARATOR.$name;if(file_exists($new)||!rename($src,$new))throw new RuntimeException('Não foi possível renomear.');return ['path'=>substr($new,strlen($this->ws->root())+1)];}
    private function move(string $src,string $dest):array{$dir=$this->ws->safe($dest,true);if(!is_dir($dir))throw new RuntimeException('Destino precisa ser pasta.');$new=$dir.DIRECTORY_SEPARATOR.basename($src);if(file_exists($new)||!rename($src,$new))throw new RuntimeException('Não foi possível mover.');return ['path'=>substr($new,strlen($this->ws->root())+1)];}
    private function trash(string $src,string $path):array{$trash=$this->ws->root().DIRECTORY_SEPARATOR.'.trash';if(!is_dir($trash)&&!mkdir($trash,0700,true))throw new RuntimeException('Não foi possível preparar a lixeira.');$id=bin2hex(random_bytes(8));$target=$trash.DIRECTORY_SEPARATOR.$id.'_'.basename($src);if(!rename($src,$target))throw new RuntimeException('Não foi possível enviar para lixeira.');file_put_contents($target.'.json',json_encode(['original'=>$path,'name'=>basename($src),'deleted_at'=>date(DATE_ATOM)],JSON_UNESCAPED_UNICODE|JSON_THROW_ON_ERROR));return ['trash_id'=>$id];}
    private function restore(string $id):array{throw new RuntimeException('Restauração ainda não está disponível; o backup permanece em .backups.');}
}
?>
